from textual.app import ComposeResult, App
from textual.widgets import Button, Static
from textual.message import Message


class MyWidget(Static):
    """A widget that sends a custom message to its parent."""

    class ButtonPressed(Message):
        """Custom message sent when button is pressed."""

        def __init__(self, button_text: str):
            self.button_text = button_text
            super().__init__()

    def compose(self) -> ComposeResult:
        yield Button("Click me!", id="my_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Send custom message when button is pressed."""
        if event.button.id == "my_button":
            self.post_message(self.ButtonPressed("Hello from MyWidget!"))


class MyApp(App):
    """Application that listens for custom messages from MyWidget."""

    def compose(self) -> ComposeResult:
        yield MyWidget(id="my_widget")

    def on_my_widget_button_pressed(self, message: MyWidget.ButtonPressed) -> None:
        """Handle ButtonPressed message from MyWidget."""
        self.title = f"Message received: {message.button_text}"


if __name__ == "__main__":
    MyApp().run()

